function pageDescription(p:Page){return ({'Complaint Registry':'Search, filter, and open authorized complaint records.','Institutions':'Browse institutions represented in the authorized case records.','Overlap Monitoring':'Review explainable case relationship suggestions before making a decision.','Workflow & History':'Follow recent recorded actions and current case status.','Transfers & Escalations':'Monitor workload movement and escalation status.','Alerts & Deadlines':'Identify cases whose recorded next-action dates need attention.','Reports & Analytics':'Explore aggregate views calculated from authorized records.','Coordination Workspace':'Review cases and coordinate follow-up among handling units.','User & Role Management':'Protected account administration for designated administrators.','Profile & Security':'Review your signed-in account and session controls.'} as Record<string,string>)[p]||'Monitor authorized complaint activity.'}
function Dashboard({kind,bureauName,profile,userId,cards,chartData,bureauData,cases,overlaps,actions,coordination,transfers,audits,lastUpdated,onRefresh,go,openMetric,openCase}:any){
 const title=kind==='administrator'?'AICTE Administrator Dashboard':kind==='bureau'?`${bureauName} Dashboard`:kind==='officer'?'Individual Officer Dashboard':kind==='oversight'?'AICTE Oversight Dashboard':'Dashboard';
 const recent=actions.slice().sort((a:any,b:any)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,5);
 const overdue=cases.filter((c:CaseRow)=>isPastNextAction(c));
 const unassigned=kind==='bureau'||kind==='administrator'?cases.filter((c:CaseRow)=>!c.assigned_officer_id):[];
 const openRequests=coordination.filter((r:any)=>r.status==='open');
 const attentionCases=[...new Map([...overdue,...unassigned,...openRequests.map((r:any)=>cases.find((c:CaseRow)=>c.id===r.complaint_id)).filter(Boolean)].map((c:any)=>[c.id,c])).values()].slice(0,6);
 const pendingDisposed=[{name:'Pending',value:cases.filter((c:CaseRow)=>c.status==='Pending').length},{name:'Disposed',value:cases.filter((c:CaseRow)=>c.status==='Disposed').length}];
 const categories=Object.entries(cases.reduce((a:Record<string,number>,c:CaseRow)=>{const k=c.category||'Uncategorized';a[k]=(a[k]||0)+1;return a},{})).map(([name,value])=>({name,value})).slice(0,8);
 const officerWorkload=Object.entries(cases.reduce((a:Record<string,number>,c:any)=>{const n=c.assigned_officer?.display_name||'Unassigned';a[n]=(a[n]||0)+1;return a},{})).map(([name,value])=>({name,value}));
 const institutions=Object.entries(cases.reduce((a:Record<string,number>,c:CaseRow)=>{const n=c.institutions?.name||'Institution unavailable';a[n]=(a[n]||0)+1;return a},{})).map(([name,value])=>({name,value})).sort((a:any,b:any)=>b.value-a.value).slice(0,8);
 const overlapByBureau=Object.entries(overlaps.reduce((a:Record<string,number>,r:any)=>{for(const c of cases.filter((x:CaseRow)=>x.id===r.source_case_id||x.id===r.target_case_id)){const n=c.bureaus?.name||'Unassigned';a[n]=(a[n]||0)+1}return a},{})).map(([name,value])=>({name,value}));
 const lastAction=(id:string)=>actions.find((a:any)=>a.complaint_id===id);
 const welcome=kind==='officer'?`Your assigned workload${profile.display_name?`, ${profile.display_name}`:''}.`:kind==='bureau'?`Authorized workload and follow-up for ${bureauName}.`:kind==='administrator'?`Organization-wide monitoring for authorized administrators${profile.display_name?`, ${profile.display_name}`:''}.`:`Read-only organization-wide monitoring${profile.display_name?`, ${profile.display_name}`:''}.`;
 return <>
  <div className="dashboard-welcome"><div><span className="tag">{kind==='administrator'?'ADMINISTRATOR':kind==='bureau'?bureauName.toUpperCase():kind==='officer'?'INDIVIDUAL OFFICER':'AICTE OFFICIAL · READ ONLY'}</span><h2>{title}</h2><p>{welcome}</p></div><div className="refresh-meta"><span>Last refreshed · auto-refreshes every minute</span><b>{lastUpdated?lastUpdated.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}):'Not yet refreshed'}</b><button className="button secondary" onClick={()=>void onRefresh()}><RefreshCw size={14}/> Refresh</button></div></div>
  <div className="kpi-grid role-kpis">{cards.map(([label,value,desc,key]:any)=><button className="kpi-card" key={key} onClick={()=>openMetric(key)} disabled={typeof value==='string'}><div className="kpi-label">{label}<span className={`kpi-icon ${key}`}>{key==='overlap'?<ArrowLeftRight size={17}/>:key==='Overdue'?<AlertTriangle size={17}/>:<FileText size={17}/>}</span></div><div className={`kpi-value ${typeof value==='string'?'small-value':''}`}>{value}</div><div className="kpi-foot">{desc}<span>{key==='deadline_config'?'i':'↗'}</span></div></button>)}</div>
  <div className="dashboard-grid">
   <section className="panel"><div className="panel-head"><div><h2>Complaint status distribution</h2><p>Counts from records visible to your role</p></div><button className="text-button" onClick={()=>go('Reports & Analytics')}>Reports ↗</button></div>{chartData.statuses.length?<div className="chart-area"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={chartData.statuses} dataKey="value" nameKey="name" innerRadius={56} outerRadius={82} paddingAngle={3}>{chartData.statuses.map((d:any,i:number)=><Cell key={d.name} fill={statusColors[d.name.toLowerCase()]||['#245b86','#0f8b8d','#c5d0dc','#6941c6'][i%4]}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer><div className="legend">{chartData.statuses.map((x:any,i:number)=><span key={x.name}><i style={{background:statusColors[x.name.toLowerCase()]||['#245b86','#0f8b8d','#c5d0dc','#6941c6'][i%4]}}/>{x.name}<b>{x.value}</b></span>)}</div></div>:<Empty title="No status data" text="Counts will appear when authorized complaint records are available."/>}</section>
   {(kind==='administrator'||kind==='oversight')&&<section className="panel"><div className="panel-head"><div><h2>Bureau / Cell workload</h2><p>Authorized case count by handling unit</p></div></div>{bureauData.length?<div className="bar-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={bureauData} layout="vertical" margin={{left:10,right:20}}><CartesianGrid strokeDasharray="3 3" horizontal={false}/><XAxis type="number" allowDecimals={false}/><YAxis type="category" dataKey="name" width={90}/><Tooltip/><Bar dataKey="value" fill="#0f8b8d" radius={[0,5,5,0]}/></BarChart></ResponsiveContainer></div>:<Empty title="No workload data" text="Bureau workload is calculated from authorized case records."/>}</section>}
   {kind==='bureau'&&<section className="panel"><div className="panel-head"><div><h2>Assigned officer workload</h2><p>Names are shown only within your managed Bureau/Cell</p></div></div>{officerWorkload.length?<div className="bar-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={officerWorkload} layout="vertical" margin={{left:10,right:20}}><CartesianGrid strokeDasharray="3 3" horizontal={false}/><XAxis type="number" allowDecimals={false}/><YAxis type="category" dataKey="name" width={110}/><Tooltip/><Bar dataKey="value" fill="#0f8b8d" radius={[0,5,5,0]}/></BarChart></ResponsiveContainer></div>:<Empty title="No officer assignments" text="Workload appears when complaints are assigned to active officers in this Bureau/Cell."/>}</section>}
   {kind==='officer'&&<section className="panel"><div className="panel-head"><div><h2>Pending versus disposed</h2><p>Your assigned cases only</p></div></div><div className="bar-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={pendingDisposed}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name"/><YAxis allowDecimals={false}/><Tooltip/><Bar dataKey="value" fill="#245b86" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></section>}
   {(kind==='administrator'||kind==='oversight'||kind==='bureau')&&<section className="panel"><div className="panel-head"><div><h2>Pending versus disposed</h2><p>{kind==='bureau'?`${bureauName} scope`:kind==='administrator'?'Administrator authorized scope':'AICTE authorized read scope'}</p></div></div><div className="bar-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={pendingDisposed}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name"/><YAxis allowDecimals={false}/><Tooltip/><Bar dataKey="value" fill="#245b86" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></section>}
   <section className="panel"><div className="panel-head"><div><h2>Monthly intake and recorded disposals</h2><p>Received dates and recorded disposal actions</p></div></div>{chartData.trend.length?<div className="bar-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={chartData.trend}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name"/><YAxis allowDecimals={false}/><Tooltip/><Line type="monotone" dataKey="received" name="Received" stroke="#245b86" strokeWidth={2}/><Line type="monotone" dataKey="disposed" name="Recorded disposed" stroke="#0f8b8d" strokeWidth={2}/></LineChart></ResponsiveContainer></div>:<Empty title="No dated records" text="Monthly trends need recorded received dates or disposal actions."/>}</section>
   <section className="panel"><div className="panel-head"><div><h2>Pending case ageing</h2><p>Age since received date; not an SLA</p></div></div>{chartData.ageing.some((x:any)=>x.value)?<div className="bar-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={chartData.ageing}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name"/><YAxis allowDecimals={false}/><Tooltip/><Bar dataKey="value" fill="#d19a4a" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div>:<Empty title="No pending cases" text="Ageing bands include only non-disposed cases."/>}</section>
   {(kind==='bureau')&&<section className="panel"><div className="panel-head"><div><h2>Complaint categories</h2><p>Current authorized Bureau/Cell cases</p></div></div>{categories.length?<div className="bar-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={categories} layout="vertical"><CartesianGrid strokeDasharray="3 3" horizontal={false}/><XAxis type="number" allowDecimals={false}/><YAxis type="category" dataKey="name" width={120}/><Tooltip/><Bar dataKey="value" fill="#245b86" radius={[0,5,5,0]}/></BarChart></ResponsiveContainer></div>:<Empty title="No category data" text="Complaint categories are not recorded yet."/>}</section>}
   {(kind==='administrator'||kind==='oversight'||kind==='bureau')&&<><section className="panel"><div className="panel-head"><div><h2>Institution-wise cases</h2><p>Highest complaint counts among records in your authorized scope</p></div></div>{institutions.length?<div className="bar-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={institutions} layout="vertical"><CartesianGrid strokeDasharray="3 3" horizontal={false}/><XAxis type="number" allowDecimals={false}/><YAxis type="category" dataKey="name" width={130}/><Tooltip/><Bar dataKey="value" fill="#245b86" radius={[0,5,5,0]}/></BarChart></ResponsiveContainer></div>:<Empty title="No institution history" text="Institution counts use authorized complaint records."/>}</section><section className="panel"><div className="panel-head"><div><h2>Cross-Bureau overlap queue</h2><p>Distribution across relationships visible to your role</p></div><button className="text-button" onClick={()=>go('Overlap Monitoring')}>Review ↗</button></div>{overlapByBureau.length?<div className="bar-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={overlapByBureau}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name"/><YAxis allowDecimals={false}/><Tooltip/><Bar dataKey="value" fill="#0f8b8d" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div>:<Empty title="No overlap suggestions" text="Only authorized, pending human-review suggestions appear here."/>}</section></>}
  </div>
  <div className="content-grid"><section className="panel"><div className="panel-head"><div><h2>{kind==='officer'?'My assigned cases':kind==='bureau'?'Bureau case queue':'Recently received cases'}</h2><p>{kind==='officer'?'Only complaints assigned to your profile':kind==='bureau'?'Cases in your managed Bureau/Cell':'Records visible under your authorization'}</p></div><button className="text-button" onClick={()=>go('Complaint Registry')}>Open registry ↗</button></div>{cases.length?<div className="table-wrap"><table><thead><tr>{kind==='officer'?<><th>CASE</th><th>INSTITUTION / ID</th><th>CATEGORY · SUBJECT</th><th>PRIORITY</th><th>STATUS</th><th>RECEIVED</th><th>LAST ACTION</th><th>NEXT ACTION</th><th>AGE / OVERDUE</th><th>COORDINATION / OVERLAP</th></>:<><th>CASE</th><th>INSTITUTION</th>{kind==='bureau'&&<th>ASSIGNED OFFICER</th>}<th>UNIT</th><th>STATUS</th><th>RECEIVED</th><th>NEXT ACTION</th></>}</tr></thead><tbody>{cases.slice().sort((a:CaseRow,b:CaseRow)=>String(b.received_at).localeCompare(String(a.received_at))).slice(0,10).map((c:any)=>{const action=lastAction(c.id);const age=Math.max(0,Math.floor((Date.now()-new Date(c.received_at).getTime())/86400000));const overdueDays=c.next_action_at&&isPastNextAction(c)?Math.max(0,Math.floor((Date.now()-new Date(c.next_action_at).getTime())/86400000)):0;const related=overlaps.some((r:any)=>r.source_case_id===c.id||r.target_case_id===c.id);const coordinating=coordination.some((r:any)=>r.complaint_id===c.id&&r.status==='open');return <tr key={c.id} onClick={()=>openCase(c.case_number)}>{kind==='officer'?<><td><b className="link-text">{c.case_number}</b></td><td>{c.institutions?.name||'—'}<small className="sub-cell">{c.institutions?.internal_id||''}</small></td><td>{c.category||'—'}<small className="sub-cell">{c.subject||'No subject recorded'}</small></td><td>{c.priority||'—'}</td><td><Status status={c.status}/></td><td>{safeDate(c.received_at)}</td><td>{safeDate(action?.created_at)}</td><td>{safeDate(c.next_action_at)}</td><td>{overdueDays?`${overdueDays}d overdue`:`${age}d pending`}</td><td>{related?'Potential overlap':coordinating?'Coordination pending':'—'}</td></>:<><td><b className="link-text">{c.case_number}</b></td><td>{c.institutions?.name||'—'}</td>{kind==='bureau'&&<td>{c.assigned_officer?.display_name||'Unassigned'}</td>}<td>{c.bureaus?.name||'Unassigned'}</td><td><Status status={c.status}/></td><td>{safeDate(c.received_at)}</td><td>{safeDate(c.next_action_at)}</td></>}</tr>})}</tbody></table></div>:<Empty title="No assigned complaints" text={kind==='officer'?'No complaints are currently assigned to your profile.':'No authorized complaint records are available yet.'}/>}</section><section className="panel attention"><div className="panel-head"><div><h2>Requires attention</h2><p>Past next-action dates and pending follow-up</p></div><span className="count-pill">{attentionCases.length}</span></div>{attentionCases.length?attentionCases.map((c:any)=><button className="attention-row attention-button" key={c.id} onClick={()=>openCase(c.case_number)}><span className="attention-icon"><AlertTriangle size={16}/></span><span><b>{c.case_number} · {c.status}</b><small>{c.institutions?.name||'Institution'} · Recorded deadline {safeDate(c.expected_disposal_at||c.next_action_at)}</small></span></button>):<Empty title="No urgent records" text="Attention items use recorded dates, open coordination requests, and overlap reviews."/>}{overlaps.slice(0,3).map((o:any)=><button className="attention-row attention-button" key={`o-${o.id}`} onClick={()=>go('Overlap Monitoring')}><span className="attention-icon"><ArrowLeftRight size={16}/></span><span><b>Potential relationship for review</b><small>{(o.match_reasons||[]).join(' · ')}</small></span></button>)}</section></div>
  <section className="panel recent-activity"><div className="panel-head"><div><h2>Recent workflow activity</h2><p>Latest recorded actions available to your role</p></div><button className="text-button" onClick={()=>go('Workflow & History')}>Workflow history ↗</button></div>{recent.length?recent.map((a:any)=><button className="activity-row" key={a.id} onClick={()=>{const c=cases.find((x:CaseRow)=>x.id===a.complaint_id);if(c)openCase(c.case_number)}}><span className="activity-icon"><Activity size={15}/></span><span><b>{cases.find((c:CaseRow)=>c.id===a.complaint_id)?.case_number||'Authorized case action'}</b><small>{a.action_type} · {a.remarks}</small></span><time>{safeDate(a.created_at)}</time></button>):<Empty title="No recent activity" text="Recorded case actions will appear here."/>}</section>{kind==='administrator'&&<section className="panel recent-activity"><div className="panel-head"><div><h2>Administrator audit history</h2><p>Recent system events; details are restricted to designated administrators</p></div></div>{audits.length?audits.map((a:any)=><div className="activity-row audit-row" key={a.id}><span className="activity-icon"><ShieldCheck size={15}/></span><span><b>{a.entity_type} · {a.action}</b><small>{a.entity_id||'System event'}</small></span><time>{safeDate(a.created_at)}</time></div>):<Empty title="No audit events" text="Audit entries appear when authorized workflow actions are recorded."/>}</section>}
 </>
}
function Registry({rows,search,setSearch,filter,setFilter,onSelect,onNew,allowCreate}:any){
 const [fromDate,setFromDate]=useState(''),[toDate,setToDate]=useState(''),[bureau,setBureau]=useState('All bureaus'),[region,setRegion]=useState('All regions'),[category,setCategory]=useState('All categories');
 const options=(values:string[])=>[...new Set(values.filter(Boolean))].sort();
 const visible=rows.filter((c:CaseRow)=>{const received=c.received_at?.slice(0,10)||'';return (!fromDate||received>=fromDate)&&(!toDate||received<=toDate)&&(bureau==='All bureaus'||c.bureaus?.name===bureau)&&(region==='All regions'||c.institutions?.region===region)&&(category==='All categories'||c.category===category)});
 const clear=()=>{setSearch('');setFilter('All statuses');setFromDate('');setToDate('');setBureau('All bureaus');setRegion('All regions');setCategory('All categories')};
 return <div className="panel"><div className="toolbar"><div className="searchbox"><Search size={16}/><input aria-label="Search cases" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Case ID, institution, AICTE ID, bureau, region…"/></div><div className="filterbox"><Filter size={15}/><select aria-label="Filter by status" value={filter} onChange={e=>setFilter(e.target.value)}>{['All statuses','Pending','Under Process','Disposed','Transferred','Escalated','Overdue','Unassigned'].map(x=><option key={x}>{x}</option>)}</select></div>{allowCreate&&<button className="button primary" onClick={onNew}><Plus size={16}/> Record complaint</button>}</div>
 <div className="registry-filters"><label>Received from<input type="date" value={fromDate} onChange={e=>setFromDate(e.target.value)}/></label><label>Received to<input type="date" value={toDate} onChange={e=>setToDate(e.target.value)}/></label><label>Bureau/Cell<select value={bureau} onChange={e=>setBureau(e.target.value)}><option>All bureaus</option>{options(rows.map((c:CaseRow)=>c.bureaus?.name||'' )).map(x=><option key={x}>{x}</option>)}</select></label><label>Region<select value={region} onChange={e=>setRegion(e.target.value)}><option>All regions</option>{options(rows.map((c:CaseRow)=>c.institutions?.region||'' )).map(x=><option key={x}>{x}</option>)}</select></label><label>Category<select value={category} onChange={e=>setCategory(e.target.value)}><option>All categories</option>{options(rows.map((c:CaseRow)=>c.category||'' )).map(x=><option key={x}>{x}</option>)}</select></label></div>
 <div className="results-line">{visible.length} authorized record{visible.length===1?'':'s'}{(search||filter!=='All statuses'||fromDate||toDate||bureau!=='All bureaus'||region!=='All regions'||category!=='All categories')&&<button className="text-button" onClick={clear}>Clear filters</button>}</div>{visible.length?<div className="table-wrap"><table><thead><tr><th>CASE ID</th><th>INSTITUTION</th><th>CATEGORY</th><th>BUREAU / CELL</th><th>STATUS</th><th>RECEIVED</th><th>NEXT ACTION</th><th>EXPECTED DISPOSAL</th></tr></thead><tbody>{visible.map((c:CaseRow)=><tr key={c.id} onClick={()=>onSelect(c)}><td><b className="link-text">{c.case_number}</b></td><td>{c.institutions?.name||'—'}<small className="sub-cell">{c.institutions?.aicte_permanent_id||c.institutions?.internal_id||''}</small></td><td>{c.category||'—'}</td><td>{c.bureaus?.name||'Unassigned'}</td><td><Status status={c.status}/></td><td>{safeDate(c.received_at)}</td><td>{safeDate(c.next_action_at)}</td><td>{safeDate(c.expected_disposal_at)}</td></tr>)}</tbody></table></div>:<Empty title="No matching complaint records" text="Try clearing filters or changing your search criteria."/>}</div>}

function Institutions({rows,cases,search,setSearch,onSelect}:any){const filtered=rows.filter((i:any)=>`${i.name} ${i.internal_id||''} ${i.aicte_permanent_id||''} ${i.region||''} ${i.address||''}`.toLowerCase().includes(search.toLowerCase()));return <div className="panel"><div className="toolbar"><div className="searchbox"><Search size={16}/><input aria-label="Search institutions" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Institution, AICTE Permanent ID, region…"/></div><div className="results-line">{filtered.length} institutions</div></div>{filtered.length?<div className="institution-grid">{filtered.map((i:any)=><button className="institution-card" key={i.id} onClick={()=>onSelect(i)}><div className="institution-icon"><Building2 size={20}/></div><div><h3>{i.name}</h3><p>{i.region||'Region not recorded'}</p><small>AICTE ID: {i.aicte_permanent_id||'Not recorded'} · Internal ID: {i.internal_id||'Not provided'}</small></div><span className="case-count">{cases.filter((c:CaseRow)=>c.institution_id===i.id).length}<small>cases</small></span></button>)}</div>:<Empty title="No institutions found" text="Institution records are managed in your configured Supabase project."/>}</div>}
function Overlap({rows,cases,onReview,openCase,canReview,canGenerate}:any){const [busy,setBusy]=useState(false),[message,setMessage]=useState('');const suggest=async()=>{if(!supabase)return;setBusy(true);setMessage('');const {data,error}=await supabase.rpc('suggest_same_institution_relationships');setBusy(false);if(error)setMessage(friendlyError(error));else setMessage(`${data||0} new cross-bureau suggestion(s) added. Same institution is not proof of related complaints.`)};return <><div className="overlap-controls"><span>Suggestions compare accessible cases linked to the same institution across bureaus.</span>{canGenerate&&<button className="button secondary" disabled={busy} onClick={()=>void suggest()}><RefreshCw size={14}/>{busy?'Checking…':'Find suggestions'}</button>}</div>{message&&<div className="notice info">{message}</div>}<div className="notice info"><Sparkles size={18}/><div><b>Human review required</b><span>Suggestions show recorded evidence only. Same institution does not mean duplicate complaint. No case is merged or changed automatically.</span></div></div><div className="panel overlap-panel"><div className="panel-head"><div><h2>Relationship review queue</h2><p>{rows.length} pending suggestion{rows.length===1?'':'s'}</p></div><span className="tag">Explainable matching</span></div>{rows.length?rows.map((r:any)=>{const a=cases.find((c:CaseRow)=>c.id===r.source_case_id),b=cases.find((c:CaseRow)=>c.id===r.target_case_id);return <div className="overlap-row" key={r.id}><div className="case-node"><small>CASE A</small><b onClick={()=>a&&openCase(a.case_number)}>{a?.case_number||'Restricted record'}</b><span>{a?.bureaus?.name||'Handling unit not shown'}</span></div><div className="relationship"><span/><small>{r.relationship_type||'Potential relationship'}</small><span/></div><div className="case-node"><small>CASE B</small><b onClick={()=>b&&openCase(b.case_number)}>{b?.case_number||'Restricted record'}</b><span>{b?.bureaus?.name||'Handling unit not shown'}</span></div><div className="reasons">{(r.match_reasons||[]).map((x:string)=><span className="reason-tag" key={x}>{x}</span>)}</div>{canReview&&<div className="overlap-actions"><button className="button primary" onClick={()=>onReview(r.id,'confirmed')}><Check size={15}/> Confirm relation</button><button className="button subtle" onClick={()=>onReview(r.id,'rejected')}>Mark unrelated</button></div>}</div>}):<Empty title="No suggestions awaiting review" text="Relationship suggestions will be listed here when available."/>}</div></>}
function Workflow({rows,openCase}:any){const entries=rows.filter((c:CaseRow)=>c.status||c.next_action_at).slice(0,30);return <div className="panel"><div className="panel-head"><div><h2>Case workflow</h2><p>Current status and next recorded action date</p></div></div>{entries.length?<div className="workflow-list">{entries.map((c:CaseRow)=><button className="workflow-row" key={c.id} onClick={()=>openCase(c.case_number)}><span className="timeline-mark"/><div><b>{c.case_number} <Status status={c.status}/></b><small>{c.institutions?.name||'Institution'} · {c.bureaus?.name||'Unassigned'}</small><small>Received {safeDate(c.received_at)} · Next action {safeDate(c.next_action_at)}</small></div></button>)}</div>:<Empty title="No workflow activity" text="Action records will appear when authorized officers log case actions."/>}</div>}
function WorkQueue({rows,transfers,profile,kind,allowAction,onAction}:any){
 const events=transfers.filter((t:any)=>kind==='administrator'||kind==='oversight'||kind==='bureau'?(kind!=='bureau'||t.from_bureau_id===profile.bureau_id||t.to_bureau_id===profile.bureau_id):rows.some((c:CaseRow)=>c.id===t.complaint_id)).sort((a:any,b:any)=>String(b.created_at).localeCompare(String(a.created_at)));
 return <div className="panel"><div className="panel-head"><div><h2>Transfer and escalation history</h2><p>Recorded movement events within your authorized scope</p></div></div>{events.length?events.map((t:any)=>{const c=rows.find((x:CaseRow)=>x.id===t.complaint_id);const direction=kind==='bureau'?(t.to_bureau_id===profile.bureau_id?'Transferred in':'Transferred out'):'';return <div className="queue-row" key={t.id}><div><b>{c?.case_number||'Authorized transfer record'}</b><small>{direction?`${direction} · `:''}{t.transfer_type} · {t.from_bureau?.name||'Unit not available'} → {t.to_bureau?.name||'Unit not available'} · {safeDate(t.created_at)}</small></div><Status status={t.transfer_type==='escalation'?'Escalated':'Transferred'}/>{allowAction&&c&&<button className="button secondary" onClick={()=>onAction(c)}>Transfer / escalate again</button>}</div>}):<Empty title="No transfer history" text="Transfer and escalation events will appear here when recorded."/>}</div>
}
function Alerts({rows,coordination=[],overlaps=[],goCase}:any){
 const due=rows.filter((c:CaseRow)=>isPastNextAction(c)).map((c:CaseRow)=>({id:`due-${c.id}`,case:c,title:'Past recorded action/disposal date',detail:`Current status: ${c.status}`,date:[c.next_action_at,c.expected_disposal_at].filter((d:any)=>d&&new Date(d)<new Date()).sort()[0]}));
 const unassigned=rows.filter((c:CaseRow)=>!c.assigned_officer_id).map((c:CaseRow)=>({id:`unassigned-${c.id}`,case:c,title:'Case requires assignment',detail:`Current status: ${c.status}`,date:c.received_at}));
 const waiting=coordination.filter((r:any)=>r.status==='open').map((r:any)=>{const c=rows.find((x:CaseRow)=>x.id===r.complaint_id);return c?{id:`coord-${r.id}`,case:c,title:'Coordination response pending',detail:'An authorized Bureau/Cell request is still open',date:r.created_at}:null}).filter(Boolean);
 const relation=overlaps.flatMap((r:any)=>{const id=r.source_case_id;const c=rows.find((x:CaseRow)=>x.id===id)||rows.find((x:CaseRow)=>x.id===r.target_case_id);return c?[{id:`relation-${r.id}`,case:c,title:'Potential relationship needs review',detail:(r.match_reasons||[]).join(' · ')||'Human review required',date:r.created_at}]:[]});
 const alerts=[...due,...unassigned,...waiting,...relation].sort((a:any,b:any)=>String(a.date).localeCompare(String(b.date)));
 return <div className="panel"><div className="panel-head"><div><h2>Requires attention</h2><p>Recorded dates, unassigned work, coordination, and overlap reviews. No SLA is assumed.</p></div></div>{alerts.length?alerts.map((a:any)=><button className="alert-row" key={a.id} onClick={()=>goCase(a.case.case_number)}><span className="alert-mark">{a.title.includes('relationship')?<ArrowLeftRight size={18}/>:<AlertTriangle size={18}/>}</span><span><b>{a.case.case_number} · {a.title}</b><small>{a.case.institutions?.name||'Institution'} · {a.detail}</small></span><time>{safeDate(a.date)}</time></button>):<Empty title="No current attention items" text="Items appear when records meet one of the explicitly supported conditions."/>}</div>
}
function Reports({chartData,bureauData,cases,onExport}:any){
 const [period,setPeriod]=useState<'monthly'|'quarterly'>('monthly');
 const monthly=chartData.trend||[];
 const trend=period==='monthly'?monthly:Object.values(monthly.reduce((acc:Record<string,any>,entry:any)=>{const date=new Date(`${entry.month}-01T00:00:00`);const year=date.getFullYear();const quarter=Math.floor(date.getMonth()/3)+1;const key=`${year}-Q${quarter}`;acc[key]??={name:`Q${quarter} ${year}`,received:0,disposed:0};acc[key].received+=entry.received;acc[key].disposed+=entry.disposed;return acc},{}));
 const byRegion=Object.entries(cases.reduce((acc:Record<string,number>,c:CaseRow)=>{const key=c.institutions?.region||'Region not recorded';acc[key]=(acc[key]||0)+1;return acc},{})).map(([name,value])=>({name,value})).sort((a:any,b:any)=>b.value-a.value);
 const disposed=cases.filter((c:CaseRow)=>c.status==='Disposed').length;const disposalRate=cases.length?Math.round(disposed*100/cases.length):0;
 return <><div className="report-toolbar"><span>Calculated from {cases.length} authorized records. Disposal rate: {disposalRate}% ({disposed} disposed). Trend uses recorded receipt and disposal action dates.</span><select aria-label="Trend period" value={period} onChange={e=>setPeriod(e.target.value as 'monthly'|'quarterly')}><option value="monthly">Monthly</option><option value="quarterly">Quarterly</option></select><button className="button secondary" onClick={onExport} disabled={!cases.length}><FileText size={15}/> Export authorized CSV</button></div><div className="chart-grid">
 <ReportChart title="Cases by status" subtitle="Current record distribution" data={chartData.statuses||[]} color="#245b86"/>
 <ReportChart title="Workload by Bureau/Cell" subtitle="Current case bureau" data={bureauData} color="#0f8b8d" vertical/>
 <ReportChart title="Cases by region" subtitle="Institution region on record" data={byRegion} color="#6941c6" vertical/>
 <ReportChart title={`${period==='monthly'?'Monthly':'Quarterly'} intake and disposal`} subtitle="Based on available dated records" data={trend} multi/>
 <ReportChart title="Pending case ageing" subtitle="Open cases grouped by days since receipt" data={chartData.ageing||[]} color="#c17b20"/>
 </div><div className="panel"><div className="panel-head"><div><h2>Status summary</h2><p>Exact counts for authorized records</p></div></div>{chartData.statuses?.length?<table><thead><tr><th>STATUS</th><th>CASES</th></tr></thead><tbody>{chartData.statuses.map((x:any)=><tr key={x.name}><td><Status status={x.name}/></td><td>{x.value}</td></tr>)}</tbody></table>:<Empty title="No records" text="Nothing to summarize yet."/>}</div></>}
function ReportChart({title,subtitle,data,color='#245b86',vertical=false,multi=false}:any){return <div className="panel"><div className="panel-head"><div><h2>{title}</h2><p>{subtitle}</p></div></div>{data.length?<div className="bar-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={data} layout={vertical?'vertical':'horizontal'}><CartesianGrid strokeDasharray="3 3" horizontal={!vertical}/>{vertical?<><XAxis type="number" allowDecimals={false}/><YAxis type="category" dataKey="name" width={110}/></>:<><XAxis dataKey="name"/><YAxis allowDecimals={false}/></>}<Tooltip/>{multi?<><Bar dataKey="received" name="Received" fill="#245b86" radius={[4,4,0,0]}/><Bar dataKey="disposed" name="Disposed" fill="#0f8b8d" radius={[4,4,0,0]}/></>:<Bar dataKey="value" fill={color} radius={vertical?[0,4,4,0]:[4,4,0,0]}/>}</BarChart></ResponsiveContainer></div>:<Empty title="No report data" text="Available authorized records will appear here."/>}</div>}

function Coordination({rows,profile,requests,bureaus,onRefresh,showToast,readOnly}:any){
 const [selected,setSelected]=useState(''),[destination,setDestination]=useState(''),[message,setMessage]=useState(''),[responses,setResponses]=useState<Record<string,string>>({}),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const submit=async()=>{setError('');if(!selected||!destination||message.trim().length<5){setError('Choose a case, destination Bureau/Cell, and enter a request of at least 5 characters.');return}if(!supabase){setError('Supabase is not configured.');return}setBusy(true);const user=(await supabase.auth.getUser()).data.user;const c=rows.find((x:CaseRow)=>x.id===selected);const {error}=await supabase.from('coordination_requests').insert({complaint_id:selected,from_bureau_id:c?.bureau_id,to_bureau_id:destination,requested_by:user?.id,message:message.trim()});setBusy(false);if(error)setError(friendlyError(error));else{showToast('Coordination request recorded');setMessage('');void onRefresh()}};
 const respond=async(id:string)=>{const response=responses[id]?.trim();if(!response||response.length<5){setError('Enter a response of at least 5 characters.');return}if(!supabase)return;setBusy(true);const user=(await supabase.auth.getUser()).data.user;const {error}=await supabase.from('coordination_requests').update({response,status:'responded',responded_by:user?.id,responded_at:new Date().toISOString()}).eq('id',id);setBusy(false);if(error)setError(friendlyError(error));else{setError('');showToast('Coordination response recorded');void onRefresh()}};
 return <div className="panel"><div className="panel-head"><div><h2>Coordination workspace</h2><p>Requests and responses are limited to your authorized cases and participating Bureau/Cells.</p></div></div>{readOnly&&<div className="notice info">Read-only access: AICTE oversight users can view authorized coordination information but cannot create or respond to requests.</div>}{error&&<div className="form-error">{error}</div>}{requests.length?requests.map((r:any)=>{const c=rows.find((x:CaseRow)=>x.id===r.complaint_id);const canSeeCase=Boolean(c);return <div className="coord-request" key={r.id}><div><b>{canSeeCase?c.case_number:'Authorized coordination request'}</b><small>{r.message}</small><small>{r.status} · {safeDate(r.created_at)}{r.response?` · Response: ${r.response}`:''}</small></div>{!readOnly&&r.status==='open'&&<div className="coord-response"><textarea rows={2} aria-label="Coordination response" value={responses[r.id]||''} onChange={e=>setResponses(x=>({...x,[r.id]:e.target.value}))} placeholder="Write a response…"/><button className="button secondary" disabled={busy} onClick={()=>void respond(r.id)}>Send response</button></div>}</div>}):<Empty title="No coordination requests" text="Requests involving your authorized cases or Bureau/Cell will appear here."/>}{!readOnly&&<div className="coordination-form"><h3>Start a coordination request</h3><label>Case<select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Select authorized case</option>{rows.map((c:CaseRow)=><option key={c.id} value={c.id}>{c.case_number} · {c.institutions?.name||'Institution'}</option>)}</select></label><label>Destination Bureau/Cell<select value={destination} onChange={e=>setDestination(e.target.value)}><option value="">Select destination</option>{bureaus.filter((b:any)=>b.id!==profile?.bureau_id).map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label>Request<textarea rows={3} value={message} onChange={e=>setMessage(e.target.value)} placeholder="Describe the coordination needed"/></label><button className="button primary" disabled={busy||!rows.length||!bureaus.length} onClick={()=>void submit()}>{busy?'Sending…':'Create coordination request'}</button></div>}</div>
}
function Admin(){return <div className="notice warning"><ShieldCheck size={18}/><div><b>Protected administration</b><span>Account provisioning is performed through Supabase Auth by a designated administrator. This workspace does not expose public signup or allow self-assigned roles. Add a secure server-side provisioning function before enabling user-management actions.</span></div></div>}
function Profile({profile,email,logout}:any){return <div className="panel profile-panel"><div className="avatar large">{(profile?.display_name||email||'U').slice(0,1).toUpperCase()}</div><div><h2>{profile?.display_name||email?.split('@')[0]}</h2><p>{email}</p><span className="tag">{profile?.role||'Official'}</span></div><button className="button secondary" onClick={logout}><LogOut size={15}/> Sign out</button><div className="profile-note"><ShieldCheck size={17}/> Your role and access scope are managed by your designated administrator.</div></div>}
function Chat({messages,setMessages,input,setInput}:any){const send=(v=input)=>{const text=v.trim();if(!text)return;setMessages((m:any)=>[...m,{from:'user',text},{from:'assistant',text:faq(text)}]);setInput('')};return <div className="chat-panel" role="dialog" aria-label="AICTE Website Help Assistant"><header><div className="chat-avatar"><CircleHelp size={18}/></div><div><b>AICTE Website Help Assistant</b><small>Local website guidance</small></div><button className="icon-btn" aria-label="Clear chat" onClick={()=>setMessages([{from:'assistant',text:'Chat cleared. I can help with using this website. What would you like to know?'}])}>↻</button></header><div className="chat-messages" aria-live="polite">{messages.map((m:any,i:number)=><div className={`bubble ${m.from}`} key={i}>{m.text}</div>)}</div><div className="suggestions">{['How do I search cases?','What does overlap mean?'].map(q=><button key={q} onClick={()=>send(q)}>{q}</button>)}</div><form className="chat-input" onSubmit={e=>{e.preventDefault();send()}}><input aria-label="Ask about website navigation" placeholder="Ask about this website…" value={input} onChange={e=>setInput(e.target.value)}/><button aria-label="Send message"><Send size={16}/></button></form></div>}

function Login({configured,onNotice}:any){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');return <div className="login-screen"><div className="login-art"><div className="login-brand"><div className="brand-mark">A</div><b>AICTE</b></div><div className="login-art-copy"><span>INSTITUTIONAL GRIEVANCE MONITORING</span><h1>Clear visibility.<br/>Coordinated action.</h1><p>A secure workspace for authorized officials to monitor institution-related complaint cases.</p></div><div className="login-art-bottom">Integrated Complaint Monitoring System <span>·</span> Prototype</div></div><main className="login-main"><form className="login-card" onSubmit={async e=>{e.preventDefault();setError('');if(!supabase){setError('Supabase is not configured. Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY to enable sign in.');return}setBusy(true);const {error}=await supabase.auth.signInWithPassword({email,password});if(error)setError(error.message);setBusy(false)}}><div className="eyebrow">SECURE OFFICIAL ACCESS</div><h2>Welcome back</h2><p>Sign in using your provisioned official account.</p>{!configured&&<div className="notice warning compact"><AlertTriangle size={17}/><span>Connect Supabase to enable authentication.</span></div>}{error&&<div className="form-error" role="alert">{error}</div>}<label>Official email<input autoComplete="username" type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@organization.gov.in"/></label><label>Password<input autoComplete="current-password" type="password" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your password"/></label><button className="button primary full" disabled={busy||!configured}>{busy?'Signing in…':'Sign in securely'}</button><small className="login-note"><ShieldCheck size={14}/> Accounts are provisioned by an authorized administrator. Public registration is disabled.</small></form><div className="login-foot">Administrative monitoring prototype · Not an official AICTE deployment</div></main></div>}
function Empty({title,text}:any){return <div className="empty"><div className="empty-icon"><FileText size={19}/></div><b>{title}</b><span>{text}</span></div>}
function Status({status}:any){return <span className={`status-badge ${statusColors[String(status).toLowerCase()]?'':'neutral'}`} style={{'--status-color':statusColors[String(status).toLowerCase()]||'#64748b'} as any}><i/>{status||'Unknown'}</span>}
function CaseModal({row,actions=[],onClose,onAction,readOnly,canAssign}:any){return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal" role="dialog" aria-modal="true" aria-label="Complaint details" onMouseDown={e=>e.stopPropagation()}><header><div><small>CASE DETAILS</small><h2>{row.case_number}</h2></div><button className="icon-btn" aria-label="Close" onClick={onClose}><X size={18}/></button></header><div className="case-detail-grid"><div><small>STATUS</small><Status status={row.status}/></div><div><small>INSTITUTION</small><b>{row.institutions?.name||'—'}</b></div><div><small>CATEGORY</small><b>{row.category||'—'}</b></div><div><small>CURRENT BUREAU</small><b>{row.bureaus?.name||'Unassigned'}</b></div><div><small>ASSIGNED OFFICER</small><b>{row.assigned_officer?.display_name||'Unassigned'}</b></div><div><small>RECEIVED</small><b>{safeDate(row.received_at)}</b></div><div><small>NEXT ACTION REQUIRED</small><b>{row.next_action_required||'Not recorded'}</b></div><div><small>NEXT ACTION DATE</small><b>{safeDate(row.next_action_at)}</b></div><div><small>EXPECTED DISPOSAL</small><b>{safeDate(row.expected_disposal_at)}</b></div></div><LocalCaseSummary caseId={row.id}/><h3>Action history · last action {actions[0]?safeDateTime(actions[0].created_at):'not recorded'}</h3>{actions.length?<div className="action-timeline">{actions.map((a:any)=><div className="action-entry" key={a.id}><i/><span><b>{a.action_type.replace('_',' ')}</b><small>{a.assigned_to_profile?.display_name?`Assigned to ${a.assigned_to_profile.display_name} · `:''}By {a.actor?.display_name||'authorized officer'} · {safeDateTime(a.created_at)} · {a.status_before||'—'} → {a.status_after||a.status_before||'No status change'}</small><p>{a.remarks}</p></span></div>)}</div>:<p className="muted">No actions recorded for this case.</p>}<div className="modal-note"><Clock3 size={16}/> Action notes and full history are loaded from the case_actions table when configured. This prototype does not fabricate case details.</div><footer>{!readOnly&&<><button className="button secondary" onClick={()=>onAction('action')}>Record action</button><button className="button secondary" onClick={()=>onAction('transfer')}>Transfer / escalate</button>{canAssign&&<button className="button secondary" onClick={()=>onAction('assignment')}>Assign / reassign</button>}</>}<button className="button primary" onClick={onClose}>Done</button></footer></div></div>}

function LocalCaseSummary({caseId}:{caseId:string}){
 const [summary,setSummary]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const generate=async()=>{setBusy(true);setError('');try{setSummary(await summarizeAuthorizedCase(caseId))}catch(e){setError(e instanceof Error?e.message:'Local summary unavailable.')}finally{setBusy(false)}};
 return <section className="local-ai-card" aria-label="Local AI case summary"><div><div><Sparkles size={15}/><b>LOCAL CASE SUMMARY</b><span>Ollama · not stored</span></div><button className="button secondary" onClick={()=>void generate()} disabled={busy}>{busy?'Summarizing…':'Generate summary'}</button></div>{busy&&<p className="muted">The authorized case record is being summarized on this computer.</p>}{error&&<p className="local-ai-error" role="alert">{error}</p>}{summary&&<div className="local-ai-result">{summary}</div>}</section>;
}
function InstitutionModal({inst,cases,onClose,openCase}:any){const rows=cases.filter((c:CaseRow)=>c.institution_id===inst.id);return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal wide" role="dialog" aria-modal="true" aria-label="Institution profile" onMouseDown={e=>e.stopPropagation()}><header><div><small>INSTITUTION PROFILE</small><h2>{inst.name}</h2></div><button className="icon-btn" onClick={onClose} aria-label="Close"><X size={18}/></button></header><div className="institution-meta"><span><b>AICTE Permanent ID</b>{inst.aicte_permanent_id||'Not recorded'}</span><span><b>Internal ID</b>{inst.internal_id||'Not recorded'}</span><span><b>Region</b>{inst.region||'Not recorded'}</span><span><b>Address</b>{inst.address||'Not recorded'}</span><span><b>Authorized cases</b>{rows.length}</span></div><h3>Complaint history</h3>{rows.length?rows.map((c:CaseRow)=><button className="history-line" key={c.id} onClick={()=>openCase(c.case_number)}><b>{c.case_number}</b><span>{c.category||'Category not recorded'} · {safeDate(c.received_at)}</span><Status status={c.status}/></button>):<Empty title="No complaints linked" text="There are no authorized case records linked to this institution."/>}</div></div>}
function ActionModal({type,row,onClose,onSuccess,institutions=[],officers=[],bureaus=[],profile}:any){const [note,setNote]=useState(''),[status,setStatus]=useState(row?.status||'Pending'),[bureau,setBureau]=useState(''),[institutionId,setInstitutionId]=useState(''),[caseNumber,setCaseNumber]=useState(''),[category,setCategory]=useState(''),[subject,setSubject]=useState(''),[workflowType,setWorkflowType]=useState('transfer'),[targetOfficer,setTargetOfficer]=useState(''),[newBureau,setNewBureau]=useState(profile?.bureau_id||''),[receivedAt,setReceivedAt]=useState(new Date().toISOString().slice(0,10)),[expectedDisposal,setExpectedDisposal]=useState(''),[nextActionRequired,setNextActionRequired]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');const submit=async(e:any)=>{e.preventDefault();setError('');if(!supabase||(!row&&type!=='case')){setError('Supabase is not configured or a case was not selected.');return}if(type!=='case'&&note.trim().length<5){setError('Please provide a brief reason or action note (at least 5 characters).');return}setBusy(true);let result:any;if(type==='case'){const user=(await supabase.auth.getUser()).data.user;const complaint={case_number:caseNumber.trim(),institution_id:institutionId,category:category.trim()||null,subject:subject.trim()||null,received_at:new Date(`${receivedAt}T00:00:00`).toISOString(),expected_disposal_at:expectedDisposal||null,next_action_required:nextActionRequired.trim()||null,status:'Pending',bureau_id:profile?.is_admin?(newBureau||null):(profile?.bureau_id||null),created_by:user?.id};let result=await supabase.from('complaints').insert(complaint);let planningFieldsSaved=true;if(result.error&&missingPlanningColumns(result.error)){const legacyComplaint={...complaint};delete (legacyComplaint as any).expected_disposal_at;delete (legacyComplaint as any).next_action_required;result=await supabase.from('complaints').insert(legacyComplaint);planningFieldsSaved=false}if(result.error)setError(friendlyError(result.error));else onSuccess(planningFieldsSaved?'Complaint record created':'Complaint created. Apply migration 202610240003 to save next-action and expected-disposal fields.');setBusy(false);return}if(type==='action'||type==='assignment'){if(type==='assignment'&&!targetOfficer){setError('Select an active officer in the case Bureau/Cell.');setBusy(false);return}result=await supabase.from('case_actions').insert({complaint_id:row.id,action_type:type==='action'?'update':'assignment',remarks:note.trim(),status_after:type==='action'?status:null,assigned_to:type==='assignment'?targetOfficer:null,actor_id:(await supabase.auth.getUser()).data.user?.id})}else{result=await supabase.from('transfers').insert({complaint_id:row.id,to_bureau_id:bureau||null,reason:note.trim(),transfer_type:workflowType,actor_id:(await supabase.auth.getUser()).data.user?.id})}if(result.error)setError(friendlyError(result.error));else onSuccess(type==='action'?'Action recorded':type==='assignment'?'Case assignment recorded':'Workflow request recorded');setBusy(false)};return <div className="modal-backdrop" onMouseDown={onClose}><form className="modal" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><header><div><small>{type==='action'?'CASE WORKFLOW':type==='assignment'?'CASE ASSIGNMENT':'TRANSFER & ESCALATION'}</small><h2>{type==='action'?'Record an action':type==='case'?'Record a complaint':type==='assignment'?'Assign or reassign case':'Record transfer or escalation'}</h2></div><button type="button" className="icon-btn" onClick={onClose} aria-label="Close"><X size={18}/></button></header>{error&&<div className="form-error">{error}</div>}{type==='case'&&<>{profile?.is_admin&&<label>Bureau / Cell<select required value={newBureau} onChange={e=>setNewBureau(e.target.value)}><option value="">Select Bureau/Cell</option>{bureaus.map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label>}<label>Case ID<input required minLength={3} value={caseNumber} onChange={e=>setCaseNumber(e.target.value)} placeholder="Enter the authorized case identifier"/></label><label>Date received<input type="date" required value={receivedAt} onChange={e=>setReceivedAt(e.target.value)}/></label><label>Expected disposal date<input type="date" value={expectedDisposal} onChange={e=>setExpectedDisposal(e.target.value)}/></label><label>Next action required<input value={nextActionRequired} onChange={e=>setNextActionRequired(e.target.value)} placeholder="Action or follow-up required"/></label><label>Institution<select required value={institutionId} onChange={e=>setInstitutionId(e.target.value)}><option value="">Select an institution</option>{institutions.map((i:any)=><option value={i.id} key={i.id}>{i.name} · {i.aicte_permanent_id||i.internal_id}</option>)}</select></label><label>Category<input value={category} onChange={e=>setCategory(e.target.value)} placeholder="Approved category"/></label><label>Subject<input required minLength={3} value={subject} onChange={e=>setSubject(e.target.value)} placeholder="Short complaint subject"/></label></>} {type==='assignment'&&<label>Active officer in this Bureau/Cell<select required value={targetOfficer} onChange={e=>setTargetOfficer(e.target.value)}><option value="">Choose an officer</option>{officers.filter((u:any)=>u.active&&u.bureau_id===row?.bureau_id&&['pgrc_officer','rb_officer','bureau_officer'].includes(u.role)).map((u:any)=><option key={u.id} value={u.id}>{u.display_name||u.id}</option>)}</select></label>}{type==='action'&&<label>Updated status<select value={status} onChange={e=>setStatus(e.target.value)}>{['Pending','Under Process','Disposed'].map(x=><option key={x}>{x}</option>)}</select></label>}{type!=='action'&&type!=='assignment'&&type!=='case'&&<><label>Workflow type<select value={workflowType} onChange={e=>setWorkflowType(e.target.value)}><option value="transfer">Transfer</option><option value="escalation">Escalation</option></select></label><label>Destination bureau ID (optional)<input value={bureau} onChange={e=>setBureau(e.target.value)} placeholder="UUID from configured bureaus"/></label></>}{type!=='case'&&<label>{type==='action'||type==='assignment'?'Action and remarks':'Reason'}<textarea required minLength={5} rows={4} value={note} onChange={e=>setNote(e.target.value)} placeholder="Describe the action taken and any follow-up…"/></label>}<p className="muted">{type==='case'?'Case records require an existing institution and an authorized case ID.':type==='assignment'?'Only a Bureau/Cell manager or administrator can assign cases; the database checks target scope.':'This action is attributed to your signed-in account and retained in the workflow history.'}</p><footer><button type="button" className="button subtle" onClick={onClose}>Cancel</button><button className="button primary" disabled={busy}>{busy?'Saving…':type==='case'?'Create authorized record':type==='assignment'?'Save assignment':'Confirm and save'}</button></footer></form></div>}
function exportCSV(cases:CaseRow[]){const columns=['case_number','institution','aicte_permanent_id','region','category','bureau','status','received_at','next_action_at','expected_disposal_at'];const escape=(v:unknown)=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const lines=[columns.map(escape).join(','),...cases.map(c=>[c.case_number,c.institutions?.name,c.institutions?.aicte_permanent_id,c.institutions?.region,c.category,c.bureaus?.name,c.status,c.received_at,c.next_action_at,c.expected_disposal_at].map(escape).join(','))];const blob=new Blob([lines.join('\r\n')],{type:'text/csv;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='authorized-complaint-report.csv';link.click();URL.revokeObjectURL(link.href)}
